  'Research Methods in Kinesiology',
  'Research Methods in Kinesiology',
  'Research Methods in Kinesiology prepares students to design, critique, conduct, analyze, and communicate research in exercise science, biomechanics, motor behavior, sport and exercise psychology, health promotion, clinical exercise, and physical activity settings. The course emphasizes research questions, literature review, quantitative and qualitative designs, sampling, measurement, instrumentation, statistics, ethics, reproducibility, reporting standards, and applied proposal development.',
  $rmkjson${"slug": "research-methods-in-kinesiology", "title": "Research Methods in Kinesiology", "description": "Research Methods in Kinesiology prepares students to design, critique, conduct, analyze, and communicate research in exercise science, biomechanics, motor behavior, sport and exercise psychology, health promotion, clinical exercise, and physical activity settings. The course emphasizes research questions, literature review, quantitative and qualitative designs, sampling, measurement, instrumentation, statistics, ethics, reproducibility, reporting standards, and applied proposal development.", "topics": [{"id": "515a52a3-0ca0-4cb8-a663-7f6cc4b3506c", "type": "topic", "title": "Research Process, Scientific Reasoning, and Kinesiology Questions", "description": "Frame research as a disciplined way to ask and answer questions about movement, exercise, health, performance, rehabilitation, and physical activity behavior.", "children": [{"id": "d36a1832-f19b-4dc0-abb2-37dc4f48fbf7", "type": "subtopic", "title": "From curiosity to answerable questions", "description": "Students learn to convert broad interests in sport, movement, health, and rehabilitation into researchable questions.", "children": [{"id": "1d6f45f2-fd11-4f40-86de-ae67058328ad", "type": "concept", "title": "Population, exposure, intervention, comparison, and outcome thinking"}, {"id": "80e493ab-5cb6-4409-ac52-a28cae1bf6f7", "type": "concept", "title": "Descriptive, predictive, explanatory, and evaluative questions"}, {"id": "20c6d0d3-7498-4fae-90b5-6871b13aa40d", "type": "concept", "title": "Feasibility and scope"}, {"id": "8bbeba86-974a-441d-bcd0-815ea665fda0", "type": "concept", "title": "Kinesiology examples across exercise physiology, biomechanics, motor behavior, and sport psychology"}]}, {"id": "d4ea7c66-acae-4638-b193-7e27bb9ce824", "type": "subtopic", "title": "Scientific reasoning", "description": "This subtopic builds the logic of evidence, uncertainty, and inference.", "children": [{"id": "a0e49c41-6f27-46c5-8441-696679b5fb71", "type": "concept", "title": "Induction and deduction"}, {"id": "878b1e6f-7a9c-4ebe-a1f2-a78de604cb30", "type": "concept", "title": "Mechanisms and models"}, {"id": "0dc5dc2c-da66-43d0-8087-6ee0feb11b77", "type": "concept", "title": "Confounding and alternative explanations"}, {"id": "3dff27fc-d95e-4c21-a7d2-4f1a03060f3f", "type": "concept", "title": "Replication and convergence of evidence"}]}, {"id": "06523ac8-794e-48cd-bfb3-a03007ed5bcd", "type": "subtopic", "title": "The research cycle", "description": "Students see research as an iterative process rather than a single assignment.", "children": [{"id": "448da246-b404-49a7-9a79-3bd481afe429", "type": "concept", "title": "Question formation"}, {"id": "de4b0fd0-46d1-4ba6-a3a2-5c64085ddb6c", "type": "concept", "title": "Design and measurement"}, {"id": "e86e13f6-3948-44b1-be5f-f6451956775b", "type": "concept", "title": "Analysis and interpretation"}, {"id": "6fd7a7ef-2d7c-428e-80bd-e9bb00ed5087", "type": "concept", "title": "Revision, dissemination, and new questions"}]}]}, {"id": "3429399a-9e47-453c-a83a-4e6f7ecc62cc", "type": "topic", "title": "Literature Search, Evidence Appraisal, and Synthesis", "description": "Teach students to find, evaluate, organize, and synthesize research rather than simply collect sources.", "children": [{"id": "5d10fee2-f736-404e-a132-8c0c7ab08d35", "type": "subtopic", "title": "Search strategy", "description": "Students learn to search systematically enough that their review is defensible.", "children": [{"id": "96ca4067-16dc-4dc8-a246-a7d73c401aa8", "type": "concept", "title": "Databases and search engines"}, {"id": "1ef2fb71-816b-4e22-b0d0-3b764e4aaf80", "type": "concept", "title": "Keywords and controlled vocabulary"}, {"id": "dba6b3b0-01f5-40df-821a-d93376d1541d", "type": "concept", "title": "Boolean logic"}, {"id": "58141f6f-98cc-4f3e-8802-a4c4feb13759", "type": "concept", "title": "Citation chasing"}]}, {"id": "6e5ad059-4501-4a93-bc03-8e65355b0da7", "type": "subtopic", "title": "Critical appraisal", "description": "Students learn to judge study quality instead of treating all articles as equal.", "children": [{"id": "bd145d12-67e9-41ec-8476-f9e151ba6758", "type": "concept", "title": "Study design fit"}, {"id": "bd85009d-7957-4777-b763-1865501c8cea", "type": "concept", "title": "Measurement quality"}, {"id": "4ce4673f-7224-4f95-9704-a2925db11fb3", "type": "concept", "title": "Bias and confounding"}, {"id": "67963b1c-3a1d-4ab9-b583-9015138f6fa7", "type": "concept", "title": "Practical and clinical significance"}]}, {"id": "66ea0741-8b52-4700-8c5f-967ad84be07c", "type": "subtopic", "title": "Synthesis", "description": "This subtopic teaches students to build an argument from evidence.", "children": [{"id": "b82f5e26-d040-436d-8ed9-653c32c353c8", "type": "concept", "title": "Annotated bibliographies"}, {"id": "f1071c3e-c81d-4f31-8f98-ea3776ab9ca9", "type": "concept", "title": "Evidence tables"}, {"id": "a56ff3b5-1d10-4f04-9096-8ddecd45f5b6", "type": "concept", "title": "Narrative synthesis"}, {"id": "41075fb8-3095-4e4c-8e34-d62cc351ab2f", "type": "concept", "title": "Identifying gaps and future directions"}]}]}, {"id": "8984b1b7-dbaf-4b5b-962a-56e031f4f3a7", "type": "topic", "title": "Theory, Conceptual Frameworks, and Hypothesis Development", "description": "Help students connect research questions to theory, mechanisms, variables, and testable predictions.", "children": [{"id": "55251d15-88af-4054-80d6-6bd6935ff3dc", "type": "subtopic", "title": "Role of theory", "description": "Theory helps students explain why variables should relate, not just whether they do.", "children": [{"id": "8e16dcc5-6a59-4d66-b987-1705826a0aed", "type": "concept", "title": "Behavior-change theory"}, {"id": "d59a0ecc-f341-4bc1-8195-c1cbd3cfd943", "type": "concept", "title": "Motor learning models"}, {"id": "10e7a062-a67e-432b-a5d0-55948e2179f5", "type": "concept", "title": "Training adaptation models"}, {"id": "e2854e49-5953-40d5-ad8d-b730d085da59", "type": "concept", "title": "Biomechanical and physiological mechanisms"}]}, {"id": "8af2bbe3-a51c-4600-9471-d3c16a6f8c22", "type": "subtopic", "title": "Variables and constructs", "description": "Students learn to define what they intend to study and how it can be observed.", "children": [{"id": "4df7339d-5564-4369-8949-8422623f0303", "type": "concept", "title": "Independent and dependent variables"}, {"id": "bd39b54e-d0c5-4a5c-9517-15d117a4a1cd", "type": "concept", "title": "Mediators and moderators"}, {"id": "b5532c0b-c36f-4d24-a834-5b9eb7ee23ea", "type": "concept", "title": "Operational definitions"}, {"id": "0c164a8c-9f81-47ed-a6f4-98e489503090", "type": "concept", "title": "Construct validity"}]}, {"id": "e94d3b0a-46f3-4edb-be19-50998d139387", "type": "subtopic", "title": "Hypotheses and aims", "description": "Clear aims keep projects aligned from literature review through analysis.", "children": [{"id": "bd932c52-5cf1-43f7-9156-b6f8f0d88e5f", "type": "concept", "title": "Directional and nondirectional hypotheses"}, {"id": "a4318fd5-04a5-4aaa-9133-95191a5e232f", "type": "concept", "title": "Primary and secondary aims"}, {"id": "b6e2e618-3f23-48c4-9a02-2cbfb6801ea1", "type": "concept", "title": "Exploratory versus confirmatory claims"}, {"id": "47abb486-5cb6-40a0-85dc-26e96b2b315d", "type": "concept", "title": "Feasible scope for undergraduate research"}]}]}, {"id": "f6478055-d063-407c-a4ab-6bf76da78437", "type": "topic", "title": "Quantitative Research Designs in Kinesiology", "description": "Build fluency with observational, correlational, longitudinal, quasi-experimental, and intervention designs common in movement and exercise science.", "children": [{"id": "dbe7b06d-9a5c-4251-be76-cbb32f4256af", "type": "subtopic", "title": "Observational designs", "description": "Students learn when observation is appropriate and what it can and cannot prove.", "children": [{"id": "bf2bbb63-3583-4dbc-a4e4-2dc97cb13a58", "type": "concept", "title": "Cross-sectional studies"}, {"id": "255f5b45-e6ae-4e8c-8d77-02a3bab19a71", "type": "concept", "title": "Case-control studies"}, {"id": "b51fcba6-d97d-49df-8805-1a50a1c6b227", "type": "concept", "title": "Cohort studies"}, {"id": "5f0f6182-d579-44f1-b541-b30c625978a3", "type": "concept", "title": "Ecological and surveillance data"}]}, {"id": "5bb44ad7-f54b-4e31-b774-f5c814e3ea83", "type": "subtopic", "title": "Correlational and predictive designs", "description": "This subtopic shows how relationships and prediction differ from causation.", "children": [{"id": "5d1a9950-ae5e-4601-b1c5-c6c3f46ef3c3", "type": "concept", "title": "Correlation"}, {"id": "1318b84c-a745-4734-b75a-899937e6cd9a", "type": "concept", "title": "Regression"}, {"id": "92e478c3-26c6-4261-b46f-628b04b5cb7a", "type": "concept", "title": "Prediction models"}, {"id": "7f793f12-b6df-45f7-bb5c-bf0a06f84afa", "type": "concept", "title": "Overfitting and validation basics"}]}, {"id": "bfb262d2-3d6e-445f-a80d-208153f44bde", "type": "subtopic", "title": "Longitudinal and repeated-measures designs", "description": "Students learn how change over time can be studied in training, injury, adherence, and development.", "children": [{"id": "d178652d-525b-4e4a-bf86-215adca1eb2c", "type": "concept", "title": "Pre-post designs"}, {"id": "50ffde60-62a0-422b-8b05-09839c20412a", "type": "concept", "title": "Repeated measures"}, {"id": "2d989b61-7de9-4482-ba56-99067319c8a4", "type": "concept", "title": "Retention and missingness"}, {"id": "364a5338-4942-40ef-8340-9a95cb175f7e", "type": "concept", "title": "Within-person variability"}]}]}, {"id": "9a94c021-2955-4292-9404-9ee9fe62dd1a", "type": "topic", "title": "Experimental Designs, Randomization, Control, and Causal Inference", "description": "Develop the design logic needed to make stronger causal claims while respecting practical constraints in human research.", "children": [{"id": "e6381cae-a81e-4dc7-b39c-3deb2450ce86", "type": "subtopic", "title": "Experiment fundamentals", "description": "Students learn the design features that support causal interpretation.", "children": [{"id": "cdbd1972-df0a-4ac0-badd-b2b6f5d2aea2", "type": "concept", "title": "Manipulation"}, {"id": "e302aee1-4164-4ee5-8dbf-62b1c1abb103", "type": "concept", "title": "Control groups"}, {"id": "37c52dfd-2ba5-42a4-9245-3db65d37fc56", "type": "concept", "title": "Random assignment"}, {"id": "50867e3c-94ca-479e-b152-30917a9de46a", "type": "concept", "title": "Blinding where feasible"}]}, {"id": "7a3c1f91-97c5-4ae5-9f82-00e618ceddd3", "type": "subtopic", "title": "Intervention trials", "description": "This subtopic connects exercise and movement interventions to rigorous evaluation.", "children": [{"id": "d3dd78e9-06ce-4618-bf28-bd49830c2eaa", "type": "concept", "title": "Training studies"}, {"id": "6215b327-ca0b-4c84-ac05-14bcb10b5a92", "type": "concept", "title": "Clinical exercise trials"}, {"id": "6e145263-3a50-406c-8358-76f47473e117", "type": "concept", "title": "Behavior-change interventions"}, {"id": "0ab54ae0-ec9e-408e-80b8-63536d78684b", "type": "concept", "title": "Pilot and feasibility trials"}]}, {"id": "d344a9d5-0aa4-4196-a9b6-4fe739bef372", "type": "subtopic", "title": "Threats to validity", "description": "Students learn where causal claims can break down.", "children": [{"id": "ca4e1545-4460-4d75-8b7c-900ec890a6af", "type": "concept", "title": "Selection bias"}, {"id": "858e7d83-e917-4b88-a726-5eea87981adf", "type": "concept", "title": "History and maturation"}, {"id": "14f7640f-c65d-4fbe-9e78-8282d1a03d44", "type": "concept", "title": "Testing and instrumentation effects"}, {"id": "6cbdc659-d752-4cfa-a731-81ed08d7adfe", "type": "concept", "title": "Contamination and adherence"}]}]}, {"id": "b44cfac6-e937-4a1f-b110-9ab24852e4eb", "type": "topic", "title": "Qualitative Methods and Interpretive Inquiry", "description": "Introduce interview, observation, focus group, and thematic approaches for studying lived experience, culture, coaching, adherence, and care contexts.", "children": [{"id": "f3e9a210-257d-4954-8a0d-ca557f9088fe", "type": "subtopic", "title": "Qualitative research questions", "description": "Students learn when qualitative methods are the right tool.", "children": [{"id": "4412a84e-c627-4a34-9064-0938a5e460fa", "type": "concept", "title": "Experience and meaning"}, {"id": "1298c4a4-b561-4125-9077-878333a2a6b0", "type": "concept", "title": "Context and culture"}, {"id": "a85ba59c-220b-48bf-aa4e-8443e606d6f2", "type": "concept", "title": "Barriers and facilitators"}, {"id": "bc216798-b2e0-4d35-9f68-bc09b65d782f", "type": "concept", "title": "Program implementation"}]}, {"id": "f1e402c7-38ce-456b-a101-2f5a8c9528a9", "type": "subtopic", "title": "Data collection", "description": "This subtopic introduces the craft of collecting rich qualitative data.", "children": [{"id": "869e9c2e-63b5-417a-bb2c-31aa8627286a", "type": "concept", "title": "Interviews"}, {"id": "ddd36785-662a-4a18-a436-9328ee60ddff", "type": "concept", "title": "Focus groups"}, {"id": "e8b9de70-226f-4131-95fc-efe11f14d9d2", "type": "concept", "title": "Observation"}, {"id": "c673db01-3010-4b07-a341-08b53fe9ad9d", "type": "concept", "title": "Field notes and reflexive memos"}]}, {"id": "90248a5c-0ff5-41b3-848c-15468d2e05b0", "type": "subtopic", "title": "Analysis and trustworthiness", "description": "Students learn how qualitative rigor is established.", "children": [{"id": "ab2a7e76-6f87-41dd-aeb9-273de2d1f87b", "type": "concept", "title": "Coding"}, {"id": "a7c3ad8e-0902-439a-b77c-158a16d1321b", "type": "concept", "title": "Thematic analysis"}, {"id": "b09830c0-cd93-4a59-aeef-674549b68400", "type": "concept", "title": "Triangulation"}, {"id": "bcbb54c9-da7d-4c2d-96bc-4111fcfef6e3", "type": "concept", "title": "Credibility, transferability, dependability, and confirmability"}]}]}, {"id": "b736edc6-03dc-47a8-adc7-47f94e2c7ed6", "type": "topic", "title": "Mixed-Methods and Translational Kinesiology Research", "description": "Show how quantitative and qualitative evidence can be integrated to answer applied questions more completely.", "children": [{"id": "5114882d-f126-4d5e-8abf-92e897617dd3", "type": "subtopic", "title": "Why mix methods", "description": "Mixed-methods designs help students answer both whether something works and how or why it works.", "children": [{"id": "ff458c4a-a326-493f-bd05-594084971fd6", "type": "concept", "title": "Complementarity"}, {"id": "ea9bbb9d-7e4e-4731-b6d0-123fbf160e64", "type": "concept", "title": "Development"}, {"id": "50d9484a-7a02-459f-8959-59ed4f3c8af8", "type": "concept", "title": "Expansion"}, {"id": "1ce47c03-6ebd-465c-b47e-9641c0e497d8", "type": "concept", "title": "Contradictory findings"}]}, {"id": "0c86a094-9ae8-48b3-8aa4-eb632ddaf121", "type": "subtopic", "title": "Common mixed designs", "description": "Students learn the structure and sequencing of integrated studies.", "children": [{"id": "bf5fd047-f12d-498a-83ea-e40759bca27e", "type": "concept", "title": "Convergent design"}, {"id": "604d85dd-6f04-4498-8073-6b4f77744f52", "type": "concept", "title": "Explanatory sequential design"}, {"id": "278b123c-1b29-4f2d-8fa0-0639bed6472d", "type": "concept", "title": "Exploratory sequential design"}, {"id": "d7af4923-e42d-4aa7-a364-f6f4a4357359", "type": "concept", "title": "Embedded design"}]}, {"id": "eb0bf42a-6190-4607-b62a-b01f6be6f28d", "type": "subtopic", "title": "Translation to practice", "description": "This subtopic connects research findings to clinics, teams, schools, communities, and fitness settings.", "children": [{"id": "620335c7-5366-4865-bb90-f291231c5278", "type": "concept", "title": "Implementation outcomes"}, {"id": "428e6318-8fd3-4d8e-983e-8c867b92dbb2", "type": "concept", "title": "Stakeholder engagement"}, {"id": "8c4150e7-39dd-4b63-97db-4da9bff612b9", "type": "concept", "title": "Feasibility and acceptability"}, {"id": "afe65d50-67be-4c9b-ae64-d9e943967fa2", "type": "concept", "title": "Knowledge translation products"}]}]}, {"id": "7a91b947-3ccf-4819-b0b5-44107d224038", "type": "topic", "title": "Survey Research, Questionnaires, and Behavioral Measurement", "description": "Teach students to design, critique, administer, and interpret surveys used in physical activity, sport, health, and behavior research.", "children": [{"id": "9e8c2c7b-1791-4954-b80d-1e2bf943dd75", "type": "subtopic", "title": "Survey design", "description": "Students learn to write questions that reduce ambiguity and bias.", "children": [{"id": "d718208a-5133-4dbb-896e-635a3d8015a8", "type": "concept", "title": "Item wording"}, {"id": "3ef0c9df-c754-42e1-a6b7-efd3ce275c02", "type": "concept", "title": "Response scales"}, {"id": "9d8da7c0-93d4-43a0-8da3-be4f57fb024c", "type": "concept", "title": "Skip logic"}, {"id": "9574db78-780e-4654-8983-03bfbcd05e98", "type": "concept", "title": "Pilot testing"}]}, {"id": "572a140c-7291-4bcf-b85f-845ff2afcf75", "type": "subtopic", "title": "Questionnaire quality", "description": "This subtopic introduces how survey measures are evaluated.", "children": [{"id": "eb771c18-0e0b-4665-b3f8-26e71c970ccf", "type": "concept", "title": "Reliability"}, {"id": "a32f1b2f-7caa-475d-9c5a-acfcbdda1042", "type": "concept", "title": "Validity evidence"}, {"id": "8365dd66-8548-419d-9119-acd5b52521da", "type": "concept", "title": "Factor structure basics"}, {"id": "9fb6ce42-34ca-4172-9bf4-3257d91bd646", "type": "concept", "title": "Floor and ceiling effects"}]}, {"id": "d8b56d63-e841-4f2c-99e0-c2fb4d942a05", "type": "subtopic", "title": "Administration and interpretation", "description": "Students learn practical and ethical issues in collecting self-report data.", "children": [{"id": "3b35a7ba-4dad-4d86-b0c7-2b045166dae5", "type": "concept", "title": "Sampling frames"}, {"id": "8dd0d4e5-ff09-4be6-af8b-f32f159bfb98", "type": "concept", "title": "Response rates"}, {"id": "25308c44-c110-4032-92ac-c07f8f72e1a1", "type": "concept", "title": "Social desirability bias"}, {"id": "6323bf08-6f9b-45cd-b548-f18bb5e19f2c", "type": "concept", "title": "Interpreting self-report physical activity"}]}]}, {"id": "21c33a4a-00c5-459a-b59d-5a6e978c66a4", "type": "topic", "title": "Sampling, Recruitment, Power, and Generalizability", "description": "Help students understand who is studied, who is missing, and how sample decisions shape inference.", "children": [{"id": "db432935-b6bc-4af4-b28f-63da41aac0ef", "type": "subtopic", "title": "Sampling strategies", "description": "Students learn how participant selection shapes study conclusions.", "children": [{"id": "8be5ece1-df5c-44ea-8fed-1131cedba4bf", "type": "concept", "title": "Convenience sampling"}, {"id": "91b800b7-7527-43f4-88b3-efa5c4a87154", "type": "concept", "title": "Random sampling"}, {"id": "80ebd1d1-11b9-4b31-a4cf-a926467a3dde", "type": "concept", "title": "Stratified sampling"}, {"id": "a7a70e23-e129-4d39-a96c-77186fff46cc", "type": "concept", "title": "Purposeful sampling"}]}, {"id": "7c176d38-8c62-4ac9-8a89-35fe6f24a4f1", "type": "subtopic", "title": "Recruitment and retention", "description": "This subtopic focuses on realistic, ethical ways to enroll and keep participants.", "children": [{"id": "6901bd0a-8168-4c94-8fd8-8432caf2e087", "type": "concept", "title": "Inclusion and exclusion criteria"}, {"id": "daea002d-ea13-44ad-81ac-b7c6c1c3dc0d", "type": "concept", "title": "Recruitment materials"}, {"id": "209ed3ef-e202-4471-a2cc-d6c40637acf0", "type": "concept", "title": "Incentives"}, {"id": "59cb7c3d-74cd-4f5a-934e-d2c8bbad171f", "type": "concept", "title": "Retention and follow-up"}]}, {"id": "a4fc5cf8-9270-4750-a870-d10d7c99dc2b", "type": "subtopic", "title": "Power and generalizability", "description": "Students learn why sample size and sample composition matter.", "children": [{"id": "21cd1f7a-1eff-43fc-b416-122673981961", "type": "concept", "title": "Effect size"}, {"id": "ec34f111-d9ad-4914-b4cf-5400ecbaeb82", "type": "concept", "title": "Statistical power"}, {"id": "b740b60a-42cc-4927-882e-59723a3f9ce8"