rion validity"}, {"id": "d214e54c-b102-40fb-b57c-f777e3f3e71c", "type": "concept", "title": "Construct validity"}, {"id": "fe77d4f5-a322-4e82-a9ed-1d29874d4306", "type": "concept", "title": "Calibration procedures"}, {"id": "4bb48e2c-c6a0-4b10-a623-587289da5dd7", "type": "concept", "title": "Protocol standardization"}]}]}, {"id": "7fb557d8-e51d-48d5-b7b0-d82f307feac8", "type": "topic", "title": "Data Management, Reproducible Workflows, and Research Integrity", "description": "Prepare students to manage data responsibly, document decisions, protect participants, and make analysis transparent.", "children": [{"id": "1d08c5ea-6344-48d4-87b7-66ca6ca0fa00", "type": "subtopic", "title": "Data organization", "description": "Students learn habits that prevent analysis errors and lost work.", "children": [{"id": "3ab18491-b958-4126-9a78-60a1dad3ff43", "type": "concept", "title": "Codebooks"}, {"id": "c7f9dce4-fa64-4183-b08a-7ef0e20317ef", "type": "concept", "title": "File naming"}, {"id": "9ade4655-e8ad-41d4-9f76-c86b0b8f0c97", "type": "concept", "title": "Raw versus cleaned data"}, {"id": "6759f37a-980c-4feb-bdff-8b2e1a825454", "type": "concept", "title": "Data dictionaries"}]}, {"id": "3f5ee6b4-1e5d-4a3b-83e9-ad305cb2901e", "type": "subtopic", "title": "Reproducible analysis", "description": "This subtopic introduces transparent workflows for modern research.", "children": [{"id": "123f47ef-398b-4958-b0e3-21730cd1c66b", "type": "concept", "title": "Analysis scripts or annotated workflows"}, {"id": "89c55d5e-2f40-4a88-a350-ad1c1e1689a5", "type": "concept", "title": "Version control concepts"}, {"id": "55609a5a-ae92-4aab-906b-03ffe8a585d2", "type": "concept", "title": "Preregistration"}, {"id": "03f12dfe-7909-49f6-9508-ae9fe773fb50", "type": "concept", "title": "Open materials and OSF projects"}]}, {"id": "50b7ec1d-0fcb-49eb-ba1f-29fda083d360", "type": "subtopic", "title": "Research integrity", "description": "Students learn the professional norms that keep evidence trustworthy.", "children": [{"id": "e9d38063-7648-411c-8632-2a6bac93ffcf", "type": "concept", "title": "Authorship and contribution"}, {"id": "c81628bd-7aa6-4784-981a-68782f9b6b46", "type": "concept", "title": "Selective reporting"}, {"id": "e59962ca-fe0a-43e8-a798-c407af20206a", "type": "concept", "title": "Questionable research practices"}, {"id": "67b02155-7ea6-4882-af59-ba25644680f5", "type": "concept", "title": "Corrections and transparency"}]}]}, {"id": "278b1d06-e32f-4c57-bbd6-9db9c75f12a0", "type": "topic", "title": "Statistical Analysis for Kinesiology Research", "description": "Connect research questions and designs to appropriate descriptive, inferential, and applied statistics.", "children": [{"id": "8441eb87-e561-4efb-bf8a-a8af735e4914", "type": "subtopic", "title": "Descriptive analysis", "description": "Students learn to summarize data accurately before testing claims.", "children": [{"id": "73eaf3f6-a6ae-4694-b580-a954ce7c149a", "type": "concept", "title": "Distributions"}, {"id": "0ba1c15b-a128-4418-8617-a8c0c9920fed", "type": "concept", "title": "Means and variability"}, {"id": "1d570d5e-e36e-4ea5-b5df-75dc02c0c5f7", "type": "concept", "title": "Tables and figures"}, {"id": "c6977ada-0e6b-489c-9c16-e1a347191aa3", "type": "concept", "title": "Outliers and missing data"}]}, {"id": "59f5ac3f-b28b-489b-a0eb-46771ad0de6b", "type": "subtopic", "title": "Inferential analysis", "description": "This subtopic connects design and question type to statistical tests.", "children": [{"id": "0f12cd8d-0e01-41bf-a27b-fd0ab5f010c7", "type": "concept", "title": "t tests and ANOVA"}, {"id": "42bf1cfd-2b8b-4e7e-9291-d2635056b251", "type": "concept", "title": "Correlation and regression"}, {"id": "0ee05af6-3e2e-4e04-80bb-2757e88478a0", "type": "concept", "title": "Chi-square tests"}, {"id": "49deca7d-4017-4455-ac7c-4df1943b7c86", "type": "concept", "title": "Nonparametric options"}]}, {"id": "b484114b-8c33-4436-b893-8756c09a6d5f", "type": "subtopic", "title": "Interpretation", 